# qx2_interleave :: ([1, 3, 5], [2, 4, 6])
def qx2_interleave(a, b):
    out = []
    for x, y in zip(a, b):
        out.append(x)
        out.append(y)
    out.extend(a[len(b):] if len(a) > len(b) else b[len(a):])
    return out

if __name__ == '__main__':
    print(qx2_interleave(([1, 3, 5], [2, 4, 6])))

